//! Tests for the JIT eval module.

use crate::error::EvalError;
use crate::jit::JitEval;

// Stub for `__esc_dispatch` which is normally generated by Cranelift codegen
// in the final binary. During tests, this symbol must be provided to satisfy
// the `extern "C"` declaration in `runtime::rt_api`.
#[unsafe(no_mangle)]
extern "C" fn __esc_dispatch(_func_idx: i32, _argc: i32, _argv: *const u64) -> u64 {
    // Return NaN-boxed undefined
    0x7FF8_0004_0000_0000_u64
}

/// NaN-boxing constants for assertions.
const QNAN: u64 = 0x7FF8_0000_0000_0000;
const TAG_INT: u64 = 0x0001;
const TAG_BOOL: u64 = 0x0002;
const TAG_NULL: u64 = 0x0003;
const TAG_UNDEFINED: u64 = 0x0004;
const TAG_SHIFT: u64 = 48;

/// Extract an i32 from a NaN-boxed value, if it's an integer.
fn unbox_i32(bits: u64) -> Option<i32> {
    let tag = (bits >> TAG_SHIFT) & 0x7;
    if bits & QNAN == QNAN && tag == TAG_INT {
        Some((bits & 0xFFFF_FFFF) as i32)
    } else {
        None
    }
}

/// Extract an f64 from a NaN-boxed value.
fn unbox_f64(bits: u64) -> Option<f64> {
    // A pure f64 is stored as its raw IEEE 754 bits.
    // If the high bits don't match the QNAN+tag pattern, it's a double.
    let tag_area = bits >> TAG_SHIFT;
    // NaN-boxed tags occupy 0x7FF9..0x7FFF range
    if (0x7FF9..=0x7FFF).contains(&tag_area) {
        return None; // This is a tagged value, not a plain f64
    }
    Some(f64::from_bits(bits))
}

/// Extract a number from a NaN-boxed value (either i32 or f64).
fn unbox_number(bits: u64) -> Option<f64> {
    if let Some(i) = unbox_i32(bits) {
        Some(f64::from(i))
    } else {
        unbox_f64(bits)
    }
}

/// Check if a NaN-boxed value is boolean true.
fn is_bool_true(bits: u64) -> bool {
    let tag = (bits >> TAG_SHIFT) & 0x7;
    bits & QNAN == QNAN && tag == TAG_BOOL && (bits & 0xFFFF_FFFF) == 1
}

/// Check if a NaN-boxed value is boolean false.
fn is_bool_false(bits: u64) -> bool {
    let tag = (bits >> TAG_SHIFT) & 0x7;
    bits & QNAN == QNAN && tag == TAG_BOOL && (bits & 0xFFFF_FFFF) == 0
}

/// Check if a NaN-boxed value is null.
fn is_null(bits: u64) -> bool {
    bits == (QNAN | (TAG_NULL << TAG_SHIFT))
}

/// Check if a NaN-boxed value is undefined.
fn is_undefined(bits: u64) -> bool {
    bits == (QNAN | (TAG_UNDEFINED << TAG_SHIFT))
}

/// Mutex to serialize runtime init/shutdown across tests, since the global
/// runtime uses mutable static state that is not safe to access concurrently.
static RT_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

/// Run a JIT test with the runtime initialized and properly shut down.
///
/// Acquires a mutex to prevent concurrent access to the global runtime state.
fn with_runtime<F: FnOnce(&mut JitEval)>(f: F) {
    let _guard = RT_LOCK.lock().unwrap();
    runtime::rt_api::__esc_rt_init();
    let mut jit = JitEval::new().unwrap();
    f(&mut jit);
    runtime::rt_api::__esc_rt_shutdown();
}

