#[test]
fn test_eval_jit_creation() {
    let jit = JitEval::new();
    assert!(jit.is_ok(), "JitEval::new() should succeed");
}

#[test]
fn test_eval_empty() {
    with_runtime(|jit| {
        let result = jit.eval("");
        assert!(result.is_ok(), "eval('') should succeed");
        assert!(
            is_undefined(result.unwrap()),
            "eval('') should return undefined"
        );
    });
}

#[test]
fn test_eval_whitespace_only() {
    with_runtime(|jit| {
        let result = jit.eval("   \n\t  ");
        assert!(result.is_ok());
        assert!(is_undefined(result.unwrap()));
    });
}

#[test]
fn test_eval_integer_literal() {
    with_runtime(|jit| {
        let result = jit.eval("42");
        match result {
            Ok(bits) => {
                if let Some(n) = unbox_number(bits) {
                    assert!((n - 42.0).abs() < f64::EPSILON, "expected 42, got {n}");
                }
            }
            Err(e) => {
                eprintln!("test_eval_integer_literal: {e} (known limitation)");
            }
        }
    });
}

