// ============================================================================
// Direct eval scope bridging tests (Steps 0.6.8 + 0.6.9)
// ============================================================================

/// Helper: create an EscEnvironment with some named variables, return its bits.
fn create_test_esc_env(bindings: &[(&str, u64)]) -> u64 {
    use runtime::rt_api::{
        __esc_rt_esc_env_create, __esc_rt_esc_env_populate_slot_map, __esc_rt_esc_env_set,
    };

    let slot_count = bindings.len() as u32;
    let env_bits = __esc_rt_esc_env_create(slot_count, 0);

    for (i, &(name, value)) in bindings.iter().enumerate() {
        // Create name string
        let rt_str = Box::new(runtime::string_ops::RtString::new(name.to_string()));
        let ptr = Box::into_raw(rt_str) as *const ();
        let name_bits = nanbox::JsValue::string(ptr).raw_bits();

        // Set up the slot map entry: name -> slot index
        let slot_bits = nanbox::JsValue::int(i as i32).raw_bits();
        __esc_rt_esc_env_populate_slot_map(env_bits, name_bits, slot_bits);

        // Set the slot value
        __esc_rt_esc_env_set(env_bits, i as u32, value);
    }

    env_bits
}

/// Helper: run eval_direct with the runtime initialized.
fn with_runtime_direct<F: FnOnce(&mut JitEval)>(f: F) {
    let _guard = RT_LOCK.lock().unwrap();
    runtime::rt_api::__esc_rt_init();
    crate::register_eval_runtime();
    let mut jit = JitEval::new().unwrap();
    f(&mut jit);
    runtime::rt_api::__esc_rt_shutdown();
}

#[ignore = "ESC-4: direct-eval scope bridging RATIFIED-NOT-IMPLEMENTED"]
#[test]
#[allow(clippy::collapsible_if)]
fn test_eval_direct_self_contained_expression() {
    with_runtime_direct(|jit| {
        let result = jit.eval_direct("2 + 3", 0, 0, 0, false);
        if let Ok(bits) = result {
            if let Some(n) = unbox_number(bits) {
                assert!(
                    (n - 5.0).abs() < f64::EPSILON,
                    "eval_direct('2 + 3') should be 5, got {n}"
                );
            }
        }
    });
}

