#[ignore = "ESC-4: direct-eval scope bridging RATIFIED-NOT-IMPLEMENTED"]
#[test]
#[allow(clippy::collapsible_if)]
fn test_eval_direct_strict_mode_var_confined() {
    // In strict mode, var declarations should be confined to the eval's own scope
    with_runtime_direct(|jit| {
        let var_env = create_test_esc_env(&[]);

        let result = jit.eval_direct("var x = 42; x", 0, var_env, 0, true);
        if let Ok(bits) = result {
            if let Some(n) = unbox_number(bits) {
                assert!(
                    (n - 42.0).abs() < f64::EPSILON,
                    "strict eval 'var x = 42; x' should return 42, got {n}"
                );
            }
        }
    });
}

