fn test_eval_direct_with_env_pointers() {
    with_runtime_direct(|jit| {
        let lex_env = create_test_esc_env(&[("x", nanbox::JsValue::int(100).raw_bits())]);
        let var_env = create_test_esc_env(&[]);

        // The eval code doesn't reference 'x' from the outer scope,
        // but having env pointers should not cause issues
        let result = jit.eval_direct("5 + 5", lex_env, var_env, 0, false);
        if let Ok(bits) = result {
            if let Some(n) = unbox_number(bits) {
                assert!(
                    (n - 10.0).abs() < f64::EPSILON,
                    "eval '5 + 5' with env should return 10, got {n}"
                );
            }
        }
    });
}
