#[test]
fn test_eval_direct_register_callback() {
    // Test that register_eval_runtime can be called without panicking
    let _guard = RT_LOCK.lock().unwrap();
    runtime::rt_api::__esc_rt_init();
    crate::register_eval_runtime();
    // Double registration should be harmless (OnceLock ignores second set)
    crate::register_eval_runtime();
    runtime::rt_api::__esc_rt_shutdown();
}

#[test]
fn test_eval_direct_rt_call_eval_direct_non_string() {
    // The runtime ABI function should pass through non-string arguments
    let _guard = RT_LOCK.lock().unwrap();
    runtime::rt_api::__esc_rt_init();

    let int_bits = nanbox::JsValue::int(42).raw_bits();
    let result = runtime::rt_api::__esc_rt_call_eval_direct(int_bits, 0, std::ptr::null());
    // Per ES spec: if the argument to eval is not a string, return it directly
    assert_eq!(
        result, int_bits,
        "non-string argument should be passed through"
    );

    runtime::rt_api::__esc_rt_shutdown();
}

#[test]
fn test_collect_var_declarations() {
    // Test the var declaration collection helper
    let _guard = RT_LOCK.lock().unwrap();
    runtime::rt_api::__esc_rt_init();

    let vars = crate::jit::collect_var_declarations("var x = 1; var y = 2; let z = 3;");
    assert!(vars.contains(&"x".to_string()), "should find var x");
    assert!(vars.contains(&"y".to_string()), "should find var y");
    assert!(!vars.contains(&"z".to_string()), "should NOT find let z");

    runtime::rt_api::__esc_rt_shutdown();
}

#[test]
fn test_collect_var_declarations_function() {
    // Function declarations in sloppy eval should be collected
    let _guard = RT_LOCK.lock().unwrap();
    runtime::rt_api::__esc_rt_init();

    let vars = crate::jit::collect_var_declarations("function foo() {} var bar = 1;");
    assert!(
        vars.contains(&"foo".to_string()),
        "should find function foo"
    );
    assert!(vars.contains(&"bar".to_string()), "should find var bar");

    runtime::rt_api::__esc_rt_shutdown();
}

